            CompromisedHosts: nonNilStrings(t.CompromisedHosts),
            FirstSeen:        t.FirstSeen,
            LastSeen:         t.LastSeen,
            RiskScore:        t.RiskScore,
        })
    case "dns_tunneling":
        return json.Marshal(struct {
            ThreatType  string  `json:"threat_type"`
            SourceIP    string  `json:"source_ip"`
            QueryCount  int     `json:"query_count"`
            AvgPayload  float64 `json:"avg_payload"`
            FirstSeen   string  `json:"first_seen"`
            LastSeen    string  `json:"last_seen"`
            RiskScore   float64 `json:"risk_score"`
        }{
            ThreatType: t.ThreatType,
            SourceIP:   t.SourceIP,
            QueryCount: t.QueryCount,
            AvgPayload: t.AvgPayload,
            FirstSeen:  t.FirstSeen,
            LastSeen:   t.LastSeen,
            RiskScore:  t.RiskScore,
        })
    }
    return json.Marshal(struct {
        ThreatType string  `json:"threat_type"`
        RiskScore  float64 `json:"risk_score"`
    }{
        ThreatType: t.ThreatType,
        RiskScore:  t.RiskScore,
    })
}

func nonNilStrings(s []string) []string {
    if s == nil {
        return []string{}
    }
    return s
}

func nonNilInts(s []int) []int {
    if s == nil {
        return []int{}
    }
    return s
}

func sortEvents(events []Event) {
    sort.SliceStable(events, func(i, j int) bool {
        ti, errI := parseTime(events[i].Timestamp)
        tj, errJ := parseTime(events[j].Timestamp)
        if errI == nil && errJ == nil {
            if ti.Before(tj) {
                return true
            }
            if tj.Before(ti) {
                return false
            }
            return events[i].Timestamp < events[j].Timestamp
        }
        return events[i].Timestamp < events[j].Timestamp
    })
}

func eventTime(e Event) (time.Time, bool) {
    t, err := parseTime(e.Timestamp)
    return t, err == nil
}

func detectThreats(events []Event) []Threat {
    sortEvents(events)
    var threats []Threat
    threats = append(threats, detectBruteForce(events)...)
    threats = append(threats, detectPortScan(events)...)
    threats = append(threats, detectDataExfiltration(events)...)
    threats = append(threats, detectPrivilegeEscalation(events)...)
    threats = append(threats, detectLateralMovement(events)...)
    threats = append(threats, detectDNSTunneling(events)...)
    sortThreats(threats)
    return threats
}

func sortThreats(threats []Threat) {
    sort.SliceStable(threats, func(i, j int) bool {
        if threats[i].RiskScore != threats[j].RiskScore {
            return threats[i].RiskScore > threats[j].RiskScore
        }
        if !threats[i].firstTime.Equal(threats[j].firstTime) {
            return threats[i].firstTime.Before(threats[j].firstTime)
        }
        return threats[i].ThreatType < threats[j].ThreatType
    })
}

func detectBruteForce(events []Event) []Threat {
    byIP := make(map[string][]Event)
    for _, e := range events {
        if e.EventType == "auth_failure" {
            byIP[e.SourceIP] = append(byIP[e.SourceIP], e)
        }
    }

    var threats []Threat
    for ip, evs := range byIP {
        for i := 0; i < len(evs); i++ {
            start, ok := eventTime(evs[i])
            if !ok {
                continue
            }
            var window []Event
            for j := i; j < len(evs); j++ {
                t, ok := eventTime(evs[j])
                if !ok {
                    continue
                }
                if t.Sub(start) <= 60*time.Second {
                    window = append(window, evs[j])
                } else {
                    break
                }
            }
            if len(window) >= 5 {
                users := make([]string, 0, len(window))
                for _, e := range window {
                    users = append(users, e.User)
                }
                users = uniqueSortedStrings(users)
                risk := float64(len(window)) * 5.0
                if len(users) > 3 {
                    risk = float64(len(window)) * 10.0
                }
                last, ok := eventTime(window[len(window)-1])
                if !ok {
                    last = start
                }
                threats = append(threats, Threat{
                    ThreatType:  "brute_force",
                    SourceIP:    ip,
                    Count:       len(window),
                    FirstSeen:   window[0].Timestamp,
                    LastSeen:    window[len(window)-1].Timestamp,
                    TargetUsers: users,
                    RiskScore:   risk,
                    firstTime:   start,
                    lastTime:    last,
                })
                break
            }
        }
    }
    return threats
}

func detectPortScan(events []Event) []Threat {
    byPair := make(map[string][]Event)
    for _, e := range events {
        if e.EventType == "connection" || e.EventType == "port_scan" {
            key := e.SourceIP + "|" + e.DestIP
            byPair[key] = append(byPair[key], e)
        }
    }

    var threats []Threat
    for pair, evs := range byPair {
        parts := splitKey(pair)
        ip := parts[0]
        dest := parts[1]
        for i := 0; i < len(evs); i++ {
            start, ok := eventTime(evs[i])
            if !ok {
                continue
            }
            var window []Event
            for j := i; j < len(evs); j++ {
                t, ok := eventTime(evs[j])
                if !ok {
                    continue
                }
                if t.Sub(start) <= 300*time.Second {
                    window = append(window, evs[j])
                } else {
                    break
                }
            }
            ports := make([]int, 0, len(window))
            for _, e := range window {
                ports = append(ports, e.DestPort)
            }
            ports = uniqueSortedInts(ports)
            if len(ports) >= 10 {
                risk := float64(len(ports)) * 3.0
                if hasSensitivePort(ports) {
                    risk += 20.0
                }
                last, ok := eventTime(window[len(window)-1])
                if !ok {
                    last = start
                }
                threats = append(threats, Threat{
                    ThreatType:   "port_scan",
                    SourceIP:      ip,
                    DestIP:        dest,
                    PortsScanned:  ports,
                    FirstSeen:     window[0].Timestamp,
                    LastSeen:      window[len(window)-1].Timestamp,
                    RiskScore:     risk,
                    firstTime:     start,
                    lastTime:      last,
                })
                break
            }
        }
    }
    return threats
}

func hasSensitivePort(ports []int) bool {
    sensitive := map[int]bool{22: true, 3389: true, 445: true, 1433: true, 3306: true, 5432: true}
    for _, p := range ports {
        if sensitive[p] {
            return true
        }
    }
    return false
}

func detectDataExfiltration(events []Event) []Threat {
    byIP := make(map[string][]Event)
    for _, e := range events {
        if e.Action == "ALLOW" {
            byIP[e.SourceIP] = append(byIP[e.SourceIP], e)
        }
    }

    var threats []Threat
    for ip, evs := range byIP {
        for i := 0; i < len(evs); i++ {
            start, ok := eventTime(evs[i])
            if !ok {
                continue
            }
            var window []Event
            var total int64
            for j := i; j < len(evs); j++ {
                t, ok := eventTime(evs[j])
                if !ok {
                    continue
                }
                if t.Sub(start) <= 3600*time.Second {
                    window = append(window, evs[j])
                    total += evs[j].PayloadSize
                } else {
                    break
                }
            }
            if total > 104857600 {
                dests := make([]string, 0, len(window))
                for _, e := range window {
                    dests = append(dests, e.DestIP)
                }
                dests = uniqueSortedStrings(dests)
                risk := (float64(total) / 1048576.0) * 0.5
                last, ok := eventTime(window[len(window)-1])
                if !ok {
                    last = start
                }
                threats = append(threats, Threat{
                    ThreatType:  "data_exfiltration",
                    SourceIP:    ip,
                    TotalBytes:  total,
                    FirstSeen:   window[0].Timestamp,
                    LastSeen:    window[len(window)-1].Timestamp,
                    DestIPs:     dests,
                    RiskScore:   risk,
                    firstTime:   start,
                    lastTime:    last,
                })
                break
            }
        }
    }
    return threats
}

func detectPrivilegeEscalation(events []Event) []Threat {
    byUserFail := make(map[string][]Event)
    var elevatedSuccess []Event
    for _, e := range events {
        if e.EventType == "auth_failure" {
            byUserFail[e.User] = append(byUserFail[e.User], e)
        }
        if e.EventType == "auth_success" && e.Metadata["privilege_change"] == "elevated" {
            elevatedSuccess = append(elevatedSuccess, e)
        }
    }

    sortEvents(elevatedSuccess)

    seenUser := make(map[string]bool)
    var threats []Threat
    for _, e := range elevatedSuccess {
        if seenUser[e.User] {
            continue
        }
        t, ok := eventTime(e)
        if !ok {
            continue
        }
        start := t.Add(-300 * time.Second)
        count := 0
        for _, f := range byUserFail[e.User] {
            ft, ok := eventTime(f)
            if !ok {
                continue
            }
            if !ft.Before(start) && !ft.After(t) {
                count++
            }
        }
        if count >= 1 {
            seenUser[e.User] = true
            threats = append(threats, Threat{
                ThreatType:    "privilege_escalation",
                User:          e.User,
                SourceIP:      e.SourceIP,
                Timestamp:     e.Timestamp,
                PriorFailures: count,
                RiskScore:     float64(count) * 25.0,
                FirstSeen:     e.Timestamp,
                LastSeen:      e.Timestamp,
                firstTime:     t,
                lastTime:      t,
            })
        }
    }
    return threats
}

func detectLateralMovement(events []Event) []Threat {
    byIPSuccess := make(map[string][]Event)
    byPairFail := make(map[string][]Event)
    for _, e := range events {
        if e.EventType == "auth_success" {
            byIPSuccess[e.SourceIP] = append(byIPSuccess[e.SourceIP], e)
        }
        if e.EventType == "auth_failure" {
            key := e.SourceIP + "|" + e.DestIP
            byPairFail[key] = append(byPairFail[key], e)
        }
    }

    var threats []Threat
    for ip, evs := range byIPSuccess {
        for i := 0; i < len(evs); i++ {
            start, ok := eventTime(evs[i])
            if !ok {
                continue
            }
            var window []Event
            for j := i; j < len(evs); j++ {
                t, ok := eventTime(evs[j])
                if !ok {
                    continue
                }
                if t.Sub(start) <= 600*time.Second {
                    window = append(window, evs[j])
                } else {
                    break
                }
            }
            hosts := make(map[string]bool)
            for _, e := range window {
                et, ok := eventTime(e)
                if !ok {
                    continue
                }
                failStart := et.Add(-300 * time.Second)
                key := e.SourceIP + "|" + e.DestIP
                for _, f := range byPairFail[key] {
                    ft, ok := eventTime(f)
                    if !ok {
                        continue
                    }
                    if !ft.Before(failStart) && !ft.After(et) {
                        hosts[e.DestIP] = true
                        break
                    }
                }
            }
            if len(hosts) >= 3 {
                compromised := make([]string, 0, len(hosts))
                for h := range hosts {
                    compromised = append(compromised, h)
                }
                compromised = uniqueSortedStrings(compromised)
                risk := float64(len(compromised)) * 40.0
                last, ok := eventTime(window[len(window)-1])
                if !ok {
                    last = start
                }
                threats = append(threats, Threat{
                    ThreatType:       "lateral_movement",
                    SourceIP:         ip,
                    CompromisedHosts: compromised,
                    FirstSeen:        window[0].Timestamp,
                    LastSeen:         window[len(window)-1].Timestamp,
                    RiskScore:        risk,
                    firstTime:        start,
                    lastTime:         last,
                })
                break
            }
        }
    }
    return threats
}

func detectDNSTunneling(events []Event) []Threat {
    byIP := make(map[string][]Event)
    for _, e := range events {
        if e.EventType == "dns_query" {
            byIP[e.SourceIP] = append(byIP[e.SourceIP], e)
        }
    }

    var threats []Threat
    for ip, evs := range byIP {
        for i := 0; i < len(evs); i++ {
            start, ok := eventTime(evs[i])
            if !ok {
                continue
            }
            var window []Event
            var total int64
            for j := i; j < len(evs); j++ {
                t, ok := eventTime(evs[j])
                if !ok {
                    continue
                }
                if t.Sub(start) <= 60*time.Second {
                    window = append(window, evs[j])
                    total += evs[j].PayloadSize
                } else {
                    break
                }
            }
            if len(window) >= 50 {
                avg := float64(total) / float64(len(window))
                if avg > 512 {
                    risk := (avg / 512.0) * float64(len(window)) * 0.5
                    last, ok := eventTime(window[len(window)-1])
                    if !ok {
                        last = start
                    }
                    threats = append(threats, Threat{
                        ThreatType:  "dns_tunneling",
                        SourceIP:    ip,
                        QueryCount:  len(window),
                        AvgPayload:  round2(avg),
                        FirstSeen:   window[0].Timestamp,
                        LastSeen:    window[len(window)-1].Timestamp,
                        RiskScore:   risk,
                        firstTime:   start,
                        lastTime:    last,
                    })
                    break
                }
            }
        }
    }
    return threats
}

func splitKey(key string) []string {
    for i := 0; i < len(key); i++ {
        if key[i] == '|' {
            return []string{key[:i], key[i+1:]}
        }
    }
    return []string{key, ""}
}
