func detectChains(threats []Threat) []Chain {
    byIP := make(map[string][]Threat)
    for _, t := range threats {
        byIP[t.SourceIP] = append(byIP[t.SourceIP], t)
    }

    var chains []Chain
    for ip, ts := range byIP {
        chains = append(chains, detectReconExploitExfil(ip, ts)...)
        chains = append(chains, detectCredentialLateral(ip, ts)...)
    }

    sortChains(chains)
    return chains
}

func detectReconExploitExfil(ip string, threats []Threat) []Chain {
    var portScans []Threat
    var exploits []Threat
    var exfils []Threat
    for _, t := range threats {
        switch t.ThreatType {
        case "port_scan":
            portScans = append(portScans, t)
        case "brute_force", "privilege_escalation":
            exploits = append(exploits, t)
        case "data_exfiltration":
            exfils = append(exfils, t)
        }
    }

    sortThreatsByFirstSeen(portScans)
    sortThreatsByFirstSeen(exploits)
    sortThreatsByFirstSeen(exfils)

    for _, ps := range portScans {
        for _, ex := range exploits {
            if !ex.firstTime.After(ps.firstTime) {
                continue
            }
            for _, ef := range exfils {
                if !ef.firstTime.After(ex.firstTime) {
                    continue
                }
                stages := []string{ps.ThreatType, ex.ThreatType, ef.ThreatType}
                first := ps.firstTime
                last := ps.lastTime
                if ex.firstTime.Before(first) {
                    first = ex.firstTime
                }
                if ef.firstTime.Before(first) {
                    first = ef.firstTime
                }
                if ex.lastTime.After(last) {
                    last = ex.lastTime
                }
                if ef.lastTime.After(last) {
                    last = ef.lastTime
                }
                return []Chain{{
                    ChainType:      "recon_exploit_exfil",
                    SourceIP:       ip,
                    Stages:         stages,
                    TotalRiskScore: ps.RiskScore + ex.RiskScore + ef.RiskScore,
                    FirstSeen:      first.Format(time.RFC3339),
                    LastSeen:       last.Format(time.RFC3339),
                    firstTime:      first,
                    lastTime:       last,
                }}
            }
        }
    }
    return nil
}

func detectCredentialLateral(ip string, threats []Threat) []Chain {
    var brute []Threat
    var lateral []Threat
    for _, t := range threats {
        switch t.ThreatType {
        case "brute_force":
            brute = append(brute, t)
        case "lateral_movement":
            lateral = append(lateral, t)
        }
    }

    sortThreatsByFirstSeen(brute)
    sortThreatsByFirstSeen(lateral)

    for _, b := range brute {
        for _, l := range lateral {
            if !l.firstTime.After(b.firstTime) {
                continue
            }
            stages := []string{b.ThreatType, l.ThreatType}
            first := b.firstTime
            last := b.lastTime
            if l.firstTime.Before(first) {
                first = l.firstTime
            }
            if l.lastTime.After(last) {
                last = l.lastTime
            }
            return []Chain{{
                ChainType:      "credential_lateral",
                SourceIP:       ip,
                Stages:         stages,
                TotalRiskScore: b.RiskScore + l.RiskScore,
                FirstSeen:      first.Format(time.RFC3339),
                LastSeen:       last.Format(time.RFC3339),
                firstTime:      first,
                lastTime:       last,
            }}
        }
    }
    return nil
}

func sortThreatsByFirstSeen(threats []Threat) {
    sort.SliceStable(threats, func(i, j int) bool {
        return threats[i].firstTime.Before(threats[j].firstTime)
    })
}

func sortChains(chains []Chain) {
    sort.SliceStable(chains, func(i, j int) bool {
        if chains[i].TotalRiskScore != chains[j].TotalRiskScore {
            return chains[i].TotalRiskScore > chains[j].TotalRiskScore
        }
        return chains[i].firstTime.Before(chains[j].firstTime)
    })
}
