package main

import (
    "bufio"
    "encoding/json"
    "fmt"
    "os"
    "sort"
    "time"
)

type Summary struct {
    TotalEvents    int               `json:"total_events"`
    TimeRange      TimeRange         `json:"time_range"`
    BySeverity     map[string]int    `json:"by_severity"`
    ByAction       map[string]int    `json:"by_action"`
    ByEventType    map[string]int    `json:"by_event_type"`
    TopSourceIPs   []SourceIPStat    `json:"top_source_ips"`
    TopDestPorts   []DestPortStat    `json:"top_dest_ports"`
    UniqueSourceIPs int              `json:"unique_source_ips"`
    UniqueDestIPs   int              `json:"unique_dest_ips"`
    SeverityTrend  []SeverityWindow  `json:"severity_trend"`
}

type TimeRange struct {
    Start string `json:"start"`
    End   string `json:"end"`
}

type SourceIPStat struct {
    IP          string  `json:"ip"`
    Count       int     `json:"count"`
    ThreatScore float64 `json:"threat_score"`
}

type DestPortStat struct {
    Port  int `json:"port"`
    Count int `json:"count"`
}

type SeverityWindow struct {
    WindowStart  string  `json:"window_start"`
    WindowEnd    string  `json:"window_end"`
    AvgSeverity  float64 `json:"avg_severity"`
}

func runSummarize(args []string) int {
    fs := newFlagSet("summarize")
    format := fs.String("format", "json", "output format (text|json)")
    if !parseFlags(fs, args) {
        return 1
    }
    if *format != "json" && *format != "text" {
        fmt.Fprintln(os.Stderr, "invalid format")
        return 1
    }

    events, err := readEvents()
    summary := buildSummary(events)
    if *format == "text" {
        printTextSummary(summary)
    } else {
        printJSONSummary(summary)
    }
    if err != nil {
        fmt.Fprintln(os.Stderr, err)
        return 2
    }
    return 0
}

func buildSummary(events []Event) Summary {
    s := Summary{
        TotalEvents: len(events),
        BySeverity:  make(map[string]int),
        ByAction:    make(map[string]int),
        ByEventType: make(map[string]int),
    }
    if len(events) == 0 {
        s.TimeRange = TimeRange{Start: "", End: ""}
        s.TopSourceIPs = []SourceIPStat{}
        s.TopDestPorts = []DestPortStat{}
        s.SeverityTrend = []SeverityWindow{}
        return s
    }

    var minT, maxT time.Time
    sourceCounts := make(map[string]int)
    sourceScores := make(map[string]float64)
    destIPs := make(map[string]bool)
    portCounts := make(map[int]int)

    for i, e := range events {
        t, ok := eventTime(e)
        if ok {
            if i == 0 || t.Before(minT) {
                minT = t
            }
            if i == 0 || t.After(maxT) {
                maxT = t
            }
        } else {
            if e.Timestamp != "" {
                if i == 0 || e.Timestamp < minTStr {
                    minTStr = e.Timestamp
                }
                if i == 0 || e.Timestamp > maxTStr {
                    maxTStr = e.Timestamp
                }
            }
        }
        s.BySeverity[e.Severity]++
        s.ByAction[e.Action]++
        s.ByEventType[e.EventType]++
        sourceCounts[e.SourceIP]++
        sourceScores[e.SourceIP] += float64(severityValue(e.Severity))
        destIPs[e.DestIP] = true
        portCounts[e.DestPort]++
    }

    s.TimeRange = TimeRange{
        Start: minT.Format(time.RFC3339),
        End:   maxT.Format(time.RFC3339),
    }
    s.UniqueSourceIPs = len(sourceCounts)
    s.UniqueDestIPs = len(destIPs)

    s.TopSourceIPs = topSourceIPs(sourceCounts, sourceScores)
    s.TopDestPorts = topDestPorts(portCounts)
    s.SeverityTrend = severityTrend(events, minT)

    return s
}

var minTStr, maxTStr string

func topSourceIPs(counts map[string]int, scores map[string]float64) []SourceIPStat {
    out := make([]SourceIPStat, 0, len(counts))
    for ip, c := range counts {
        out = append(out, SourceIPStat{IP: ip, Count: c, ThreatScore: scores[ip]})
    }
    sort.Slice(out, func(i, j int) bool {
        if out[i].Count != out[j].Count {
            return out[i].Count > out[j].Count
        }
        return out[i].IP < out[j].IP
    })
    if len(out) > 10 {
        out = out[:10]
    }
    return out
}

func topDestPorts(counts map[int]int) []DestPortStat {
    out := make([]DestPortStat, 0, len(counts))
    for p, c := range counts {
        out = append(out, DestPortStat{Port: p, Count: c})
    }
    sort.Slice(out, func(i, j int) bool {
        if out[i].Count != out[j].Count {
            return out[i].Count > out[j].Count
        }
        return out[i].Port < out[j].Port
    })
    if len(out) > 10 {
        out = out[:10]
    }
    return out
}

func severityTrend(events []Event, first time.Time) []SeverityWindow {
    windows := make(map[int64][]Event)
    for _, e := range events {
        t, ok := eventTime(e)
        if !ok {
            continue
        }
        offset := int64(t.Sub(first).Seconds())
        if offset < 0 {
            offset = 0
        }
        window := offset / 3600
        windows[window] = append(windows[window], e)
    }

    var keys []int64
    for k := range windows {
        keys = append(keys, k)
    }
    sort.Slice(keys, func(i, j int) bool { return keys[i] < keys[j] })

    out := make([]SeverityWindow, 0, len(keys))
    for _, k := range keys {
        evs := windows[k]
        var total float64
        for _, e := range evs {
            total += float64(severityValue(e.Severity))
        }
        avg := total / float64(len(evs))
        start := first.Add(time.Duration(k*3600) * time.Second)
        end := first.Add(time.Duration((k+1)*3600) * time.Second)
        out = append(out, SeverityWindow{
            WindowStart: start.Format(time.RFC3339),
            WindowEnd:   end.Format(time.RFC3339),
            AvgSeverity: round2(avg),
        })
    }
    return out
}

func printJSONSummary(s Summary) {
    w := bufio.NewWriter(os.Stdout)
    defer w.Flush()
    enc := json.NewEncoder(w)
    enc.SetEscapeHTML(false)
    if err := enc.Encode(s); err != nil {
        fmt.Fprintln(os.Stderr, err)
    }
}

func printTextSummary(s Summary) {
    w := bufio.NewWriter(os.Stdout)
    defer w.Flush()

    fmt.Fprintf(w, "=== Security Log Summary ===\n")
    fmt.Fprintf(w, "Total Events: %d\n", s.TotalEvents)
    fmt.Fprintf(w, "Time Range: %s to %s\n", s.TimeRange.Start, s.TimeRange.End)
    fmt.Fprintf(w, "Unique Source IPs: %d\n", s.UniqueSourceIPs)
    fmt.Fprintf(w, "Unique Dest IPs: %d\n", s.UniqueDestIPs)
    fmt.Fprintln(w)

    fmt.Fprintln(w, "--- Severity Distribution ---")
    severities := []string{"critical", "high", "medium", "low"}
    for _, sev := range severities {
        count := s.BySeverity[sev]
        if count == 0 {
            continue
        }
        pct := 0.0
        if s.TotalEvents > 0 {
            pct = float64(count) * 100.0 / float64(s.TotalEvents)
        }
        fmt.Fprintf(w, "  %s: %d (%.1f%%)\n", sev, count, pct)
    }

    fmt.Fprintln(w)
    fmt.Fprintln(w, "--- Top Source IPs ---")
    for i, src := range s.TopSourceIPs {
        fmt.Fprintf(w, "  %d. %s - %d events (threat score: %g)\n", i+1, src.IP, src.Count, src.ThreatScore)
    }

    fmt.Fprintln(w)
    fmt.Fprintln(w, "--- Action Distribution ---")
    fmt.Fprintf(w, "ALLOW: %d\n", s.ByAction["ALLOW"])
    fmt.Fprintf(w, "DENY:  %d\n", s.ByAction["DENY"])
    fmt.Fprintf(w, "DROP:  %d\n", s.ByAction["DROP"])
}
EOF

