package main

import (
    "bufio"
    "encoding/json"
    "fmt"
    "os"
    "strconv"
)

type FilterOptions struct {
    Severity    string
    Action      string
    EventType   string
    SourceIP    string
    DestIP      string
    User        string
    Since       string
    Until       string
    Port        int
    HasPort     bool
    HasMetadata string
}

func runFilter(args []string) int {
    fs := newFlagSet("filter")
    severity := fs.String("severity", "", "minimum severity level")
    action := fs.String("action", "", "exact action")
    eventType := fs.String("event-type", "", "exact event type")
    sourceIP := fs.String("source-ip", "", "exact source IP")
    destIP := fs.String("dest-ip", "", "exact dest IP")
    user := fs.String("user", "", "exact user")
    since := fs.String("since", "", "start timestamp inclusive")
    until := fs.String("until", "", "end timestamp inclusive")
    port := fs.Int("port", 0, "destination port")
    hasMetadata := fs.String("has-metadata", "", "metadata key presence")
    if !parseFlags(fs, args) {
        return 1
    }
    if *severity == "" {
        fmt.Fprintln(os.Stderr, "missing required flag: --severity")
        return 1
    }

    opts := FilterOptions{
        Severity:    *severity,
        Action:      *action,
        EventType:   *eventType,
        SourceIP:    *sourceIP,
        DestIP:      *destIP,
        User:        *user,
        Since:       *since,
        Until:       *until,
        Port:        *port,
        HasPort:     fs.Lookup("port").Value.String() != "",
        HasMetadata: *hasMetadata,
    }

    scanner := bufio.NewScanner(os.Stdin)
    scanner.Buffer(make([]byte, 1024*1024), 16*1024*1024)
    w := bufio.NewWriter(os.Stdout)
    defer w.Flush()

    lineNo := 0
    for scanner.Scan() {
        lineNo++
        line := scanner.Text()
        if line == "" {
            continue
        }
        var e Event
        if err := json.Unmarshal([]byte(line), &e); err != nil {
            fmt.Fprintf(os.Stderr, "line %d: %v\n", lineNo, err)
            return 2
        }
        if matchesFilter(e, opts) {
            fmt.Fprintln(w, line)
        }
    }
    if err := scanner.Err(); err != nil {
        fmt.Fprintln(os.Stderr, err)
        return 2
    }
    return 0
}

func matchesFilter(e Event, opts FilterOptions) bool {
    if severityValue(e.Severity) < severityValue(opts.Severity) {
        return false
    }
    if opts.Action != "" && e.Action != opts.Action {
        return false
    }
    if opts.EventType != "" && e.EventType != opts.EventType {
        return false
    }
    if opts.SourceIP != "" && e.SourceIP != opts.SourceIP {
        return false
    }
    if opts.DestIP != "" && e.DestIP != opts.DestIP {
        return false
    }
    if opts.User != "" && e.User != opts.User {
        return false
    }
    if opts.Since != "" {
        et, err1 := parseTime(e.Timestamp)
        st, err2 := parseTime(opts.Since)
        if err1 == nil && err2 == nil {
            if et.Before(st) {
                return false
            }
        } else if e.Timestamp < opts.Since {
            return false
        }
    }
    if opts.Until != "" {
        et, err1 := parseTime(e.Timestamp)
        ut, err2 := parseTime(opts.Until)
        if err1 == nil && err2 == nil {
            if et.After(ut) {
                return false
            }
        } else if e.Timestamp > opts.Until {
            return false
        }
    }
    if opts.HasPort && e.DestPort != opts.Port {
        return false
    }
    if opts.HasMetadata != "" {
        if _, ok := e.Metadata[opts.HasMetadata]; !ok {
            return false
        }
    }
    return true
}

