package main

import (
    "bufio"
    "encoding/json"
    "fmt"
    "os"
    "sort"
    "strings"
)

type ThreatInput struct {
    ThreatType   string  `json:"threat_type"`
    SourceIP     string  `json:"source_ip"`
    DestIP       string  `json:"dest_ip"`
    User         string  `json:"user"`
    Timestamp    string  `json:"timestamp"`
    PortsScanned []int   `json:"ports_scanned"`
    RiskScore    float64 `json:"risk_score"`
    raw          map[string]interface{}
}

func runRespond(args []string) int {
    fs := newFlagSet("respond")
    templatePath := fs.String("template", "", "path to response template")
    if !parseFlags(fs, args) {
        return 1
    }
    if *templatePath == "" {
        fmt.Fprintln(os.Stderr, "missing required flag: --template")
        return 1
    }

    templates, err := loadTemplate(*templatePath)
    if err != nil {
        fmt.Fprintln(os.Stderr, err)
        return 1
    }

    threats, err := readThreats()
    if err != nil {
        fmt.Fprintln(os.Stderr, err)
        return 2
    }

    sort.SliceStable(threats, func(i, j int) bool {
        if threats[i].RiskScore != threats[j].RiskScore {
            return threats[i].RiskScore > threats[j].RiskScore
        }
        return threats[i].ThreatType < threats[j].ThreatType
    })

    w := bufio.NewWriter(os.Stdout)
    defer w.Flush()
    for _, t := range threats {
        tmpl, ok := templates[t.ThreatType]
        if !ok {
            continue
        }
        cmd := substituteTemplate(tmpl, t)
        fmt.Fprintf(w, "# Response for %s from %s (risk: %g)\n", t.ThreatType, t.SourceIP, t.RiskScore)
        fmt.Fprintln(w, cmd)
    }
    return 0
}

func loadTemplate(path string) (map[string]string, error) {
    f, err := os.Open(path)
    if err != nil {
        return nil, fmt.Errorf("template file not found: %w", err)
    }
    defer f.Close()

    templates := make(map[string]string)
    scanner := bufio.NewScanner(f)
    scanner.Buffer(make([]byte, 1024*1024), 16*1024*1024)
    lineNo := 0
    for scanner.Scan() {
        lineNo++
        line := scanner.Text()
        if strings.TrimSpace(line) == "" {
            continue
        }
        idx := strings.Index(line, ":")
        if idx < 0 {
            return nil, fmt.Errorf("invalid template line %d: missing colon", lineNo)
        }
        threatType := strings.TrimSpace(line[:idx])
        action := strings.TrimSpace(line[idx+1:])
        templates[threatType] = action
    }
    if err := scanner.Err(); err != nil {
        return nil, err
    }
    return templates, nil
}

func readThreats() ([]ThreatInput, error) {
    scanner := bufio.NewScanner(os.Stdin)
    scanner.Buffer(make([]byte, 1024*1024), 16*1024*1024)
    var threats []ThreatInput
    lineNo := 0
    for scanner.Scan() {
        lineNo++
        line := scanner.Text()
        if line == "" {
            continue
        }
        var raw map[string]interface{}
        if err := json.Unmarshal([]byte(line), &raw); err != nil {
            return threats, fmt.Errorf("line %d: %w", lineNo, err)
        }
        t := ThreatInput{
            ThreatType: stringValue(raw, "threat_type"),
            SourceIP:   stringValue(raw, "source_ip"),
            DestIP:     stringValue(raw, "dest_ip"),
            User:       stringValue(raw, "user"),
            Timestamp:  stringValue(raw, "timestamp"),
            RiskScore:  floatValue(raw, "risk_score"),
            raw:        raw,
        }
        t.PortsScanned = intSliceValue(raw, "ports_scanned")
        threats = append(threats, t)
    }
    if err := scanner.Err(); err != nil {
        return threats, err
    }
    return threats, nil
}

func substituteTemplate(tmpl string, t ThreatInput) string {
    replace := func(key, value string) {
        tmpl = strings.ReplaceAll(tmpl, key, value)
    }
    replace("{source_ip}", t.SourceIP)
    replace("{dest_ip}", orNA(t.DestIP))
    replace("{user}", orNA(t.User))
    replace("{timestamp}", orNA(t.Timestamp))
    if t.raw["ports_scanned"] != nil && len(t.PortsScanned) > 0 {
        replace("{ports}", joinInts(t.PortsScanned))
    } else {
        replace("{ports}", "N/A")
    }
    return tmpl
}

func orNA(s string) string {
    if s == "" {
        return "N/A"
    }
    return s
}

func stringValue(m map[string]interface{}, key string) string {
    if v, ok := m[key]; ok {
        if s, ok := v.(string); ok {
            return s
        }
        return fmt.Sprint(v)
    }
    return ""
}

func floatValue(m map[string]interface{}, key string) float64 {
    if v, ok := m[key]; ok {
        switch n := v.(type) {
        case float64:
            return n
        case int64:
            return float64(n)
        case int:
            return float64(n)
        }
    }
    return 0
}

func intSliceValue(m map[string]interface{}, key string) []int {
    v, ok := m[key]
    if !ok || v == nil {
        return nil
    }
    arr, ok := v.([]interface{})
    if !ok {
        return nil
    }
    out := make([]int, 0, len(arr))
    for _, item := range arr {
        switch n := item.(type) {
        case float64:
            out = append(out, int(n))
        case int64:
            out = append(out, int(n))
        case int:
            out = append(out, n)
        }
    }
    return out
}

func joinInts(vals []int) string {
    strs := make([]string, len(vals))
    for i, v := range vals {
        strs[i] = fmt.Sprintf("%d", v)
    }
    return strings.Join(strs, ",")
}
