)

func main() {
    if len(os.Args) < 2 {
        fmt.Fprintln(os.Stderr, "usage: secsentinel <analyze|summarize|filter|respond> [flags]")
        os.Exit(1)
    }

    var code int
    switch os.Args[1] {
    case "analyze":
        code = runAnalyze(os.Args[2:])
    case "summarize":
        code = runSummarize(os.Args[2:])
    case "filter":
        code = runFilter(os.Args[2:])
    case "respond":
        code = runRespond(os.Args[2:])
    default:
        fmt.Fprintf(os.Stderr, "invalid subcommand: %s\n", os.Args[1])
        code = 1
    }
    os.Exit(code)
}

func newFlagSet(name string) *flag.FlagSet {
    fs := flag.NewFlagSet(name, flag.ContinueOnError)
    fs.SetOutput(os.Stderr)
    fs.Usage = func() {}
    return fs
}

func parseFlags(fs *flag.FlagSet, args []string) bool {
    if err := fs.Parse(args); err != nil {
        return false
    }
    return true
}

func isFlagSet(fs *flag.FlagSet, name string) bool {
    set := false
    fs.Visit(func(f *flag.Flag) {
        if f.Name == name {
            set = true
        }
    })
    return set
}
